// Rust guideline compliant 2026-02-21
use gpui_mesh::{CellType,Cells,DataSet};
use gpui_scene3d::{Actor,Camera,GpuRenderer,Scene};
use gpui_profiler::AllocProbe;
use std::{hint::black_box,time::Instant};
fn cpu_ns()->u128 {
 let mut stamp=libc::timespec{tv_sec:0,tv_nsec:0};
 // SAFETY: stamp is valid writable storage for this synchronous clock call,
 // which retains no pointer. Its status and returned timestamp are checked.
 let result=unsafe{libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID,&mut stamp)};
 assert_eq!(result,0);assert!(stamp.tv_sec>=0 && (0..1_000_000_000).contains(&stamp.tv_nsec));
 stamp.tv_sec as u128*1_000_000_000+stamp.tv_nsec as u128
}
fn hash(bytes:&[u8])->u64 {bytes.iter().fold(0xcbf29ce484222325,|h,&v|(h^u64::from(v)).wrapping_mul(0x100000001b3))}
fn scene(kind:&str,n:usize)->Scene {
 if kind=="many" || kind=="transparent" {
  let columns=(n as f64).sqrt().ceil() as usize;let step=2.0/columns as f64;let mut scene=Scene::new();
  for i in 0..n {
   let x=-1.0+(i%columns) as f64*step;let y=-1.0+(i/columns) as f64*step;
   let data=DataSet::surface("actor",vec![[x,y,0.0],[x+step*0.8,y,0.0],[x+step*0.4,y+step*0.8,0.0]],&[[0,1,2]]);
   scene.actors.push(Actor::new(data).color([0.8,0.3,0.1,1.0]).opacity(if kind=="transparent"{0.5}else{1.0}));
  }return scene;
 }
 let data=if kind=="line" || kind=="point" {
  let (cell,arity,positions)=if kind=="line"{(CellType::Line,2,vec![[-0.5,0.0,0.0],[0.5,0.0,0.0]])}else{(CellType::Vertex,1,vec![[0.0;3]])};
  DataSet::new("primitive",positions,Cells{
   types:vec![cell;n].into(),offsets:(0..=n).map(|i|(i*arity) as u64).collect::<Vec<_>>().into(),
   connectivity:(0..n*arity).map(|i|(i%arity) as u32).collect::<Vec<_>>().into(),
  })
 } else {
  let mut d=DataSet::structured_grid("surface",[n;3],[-1.0;3],[2.0/(n-1) as f64;3]).unwrap();
  if kind=="general" {let nodes=std::sync::Arc::make_mut(&mut d.cells.connectivity);let last=nodes.len()-8;nodes[last..last+4].rotate_left(1);nodes[last+4..].rotate_left(1);}
  d
 };
 Scene::new().with_actor(Actor::new(data).color([0.8,0.3,0.1,1.0]))
}
fn measure<T>(kind:&str,n:usize,op:&str,payload:u64,image:u64,mut run:impl FnMut()->T,mut check:impl FnMut(T)){
 check(run());let(mut walls,mut cpus,mut calls,mut bytes)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
 for _ in 0..5 {
  let mut probe=AllocProbe::new();let before=cpu_ns();let start=Instant::now();let out=black_box(run());
  let wall=start.elapsed().as_nanos();let cpu=cpu_ns()-before;let a=probe.sample("upload-budget");walls.push(wall);cpus.push(cpu);calls.push(a.count);bytes.push(a.bytes);check(out);
 }
 println!(r#"{{"kind":"{kind}","n":{n},"op":"{op}","payload_bytes":{payload},"operations_per_sample":{},"image_hash":"{image:016x}","wall_ns":{walls:?},"cpu_ns":{cpus:?},"allocation_calls":{calls:?},"allocated_bytes":{bytes:?},"allocator":{}}}"#,if op=="sync"{1000}else{1},cfg!(feature="allocations"));
}
fn exercise(renderer:&GpuRenderer,kind:&str,n:usize){
 let scene=scene(kind,n);let camera=Camera::fitted(scene.bounds().unwrap());let target=renderer.create_target(32,32).unwrap();
 let mut resident=renderer.upload(&scene).unwrap();let payload=resident.geometry_bytes;
 if kind=="line"{assert_eq!(payload,n as u64*32)}if kind=="point"{assert_eq!(payload,n as u64*16)}
 renderer.render(&mut resident,&camera,&target).unwrap();let expected=renderer.read_rgba(&target).unwrap().rgba;
 let background=scene.background.map(|v|(v.clamp(0.0,1.0)*255.0) as u8);assert!(expected.as_chunks::<4>().0.iter().any(|p|p!=&background));let image=hash(&expected);
 measure(kind,n,"upload",payload,image,||renderer.upload(&scene).unwrap(),|mut out|{
  assert_eq!(out.geometry_bytes,payload);renderer.render(&mut out,&camera,&target).unwrap();assert_eq!(renderer.read_rgba(&target).unwrap().rgba,expected);
 });
 measure(kind,n,"sync",payload,image,||{for _ in 0..1000{assert!(!renderer.sync(&mut resident,&scene).unwrap())}},|()|());
 measure(kind,n,"submit",payload,image,||renderer.render(&mut resident,&camera,&target).unwrap(),|()|assert_eq!(renderer.read_rgba(&target).unwrap().rgba,expected));
 assert_eq!(scene.preparation_stats().geometry_builds,if kind=="many" || kind=="transparent"{n as u64}else{1});
}
fn main(){
 let args:Vec<_>=std::env::args().collect();
 let renderer=GpuRenderer::new(wgpu::TextureFormat::Rgba8Unorm).unwrap();
 if args.get(1).is_some_and(|a|a=="--rss"){
  let kind=&args[2];let n=args[3].parse().unwrap();let scene=scene(kind,n);let camera=Camera::fitted(scene.bounds().unwrap());
  let mut uploaded=renderer.upload(&scene).unwrap();let target=renderer.create_target(32,32).unwrap();renderer.render(&mut uploaded,&camera,&target).unwrap();
  let image=renderer.read_rgba(&target).unwrap();println!("{} {:016x}",uploaded.geometry_bytes,hash(&image.rgba));return;
 }
 for kind in ["line","point"]{for n in [256,65536,1048576]{exercise(&renderer,kind,n)}}
 for kind in ["canonical","general"]{exercise(&renderer,kind,48)}
 for kind in ["many","transparent"]{for n in [1,16,128]{exercise(&renderer,kind,n)}}
}

